PG.configure('/festivals/rama-navami/',[('','Rāma Navamī','The Birth of Rāma at Noon')],'blue','Rāma Navamī','Lord','Rāma Navamī')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/rama-navami/'
i=0
RAMA=lambda: god('#2a5aa8')
SITA=lambda: person('#c0392b')
LAKS=lambda: god('#e0a800')
DAS=lambda: god('#7a3fa0')
def cradle_baby(): return cradle()+g(0,-14,.6,baby())
def panaka(): return '<path d="M-14 0 l-4 -30 h36 l-4 30z" fill="#b5651d" opacity=".85"/><path d="M-16 -22 h32" stroke="#fff" stroke-width="2"/>'
def kosambari(): return plate()+''.join(f'<circle cx="{x}" cy="{y}" r="2.5" fill="{c}" stroke="none"/>' for x,y,c in [(-10,-5,'#e0a800'),(-4,-7,'#2a9d6f'),(3,-5,'#e0a800'),(9,-7,'#2a9d6f'),(0,-9,'#fff')])
def veena(): return vina()
def bow_r(): return bow()
def mrdanga(): return '<ellipse rx="26" ry="12" cy="-12" fill="#8a5a3a"/><ellipse cx="-26" cy="-12" rx="4" ry="11" fill="#3a2a1a"/><ellipse cx="26" cy="-12" rx="4" ry="11" fill="#3a2a1a"/>'
COV=covart('Baby Rāma in a cradle under a noon sun, with a bow above and the four brothers’ cradles, and a cup of pānaka',f'<rect width="440" height="196" fill="#e3eaf3"/>'+g(220,40,1.1,sun(22))+'<rect y="160" width="440" height="36" fill="#c9d6e6"/>'+g(220,186,1.6,cradle_baby())+g(90,190,1.2,cradle_baby())+g(350,190,1.2,cradle_baby())+g(220,110,1,bow())+g(400,190,1.2,panaka())+g(40,190,1.2,kosambari()))
pp=[foreword(i,['On the ninth day of the bright fortnight of Caitra, at noon, Kausalyā gave birth to <b>Rāma</b>. Vālmīki records the moment in astronomical detail, and India has kept the day ever since: <b>Rāma Navamī</b>, the last day of the spring nine nights that begin on '+L('/festivals/ugadi/','Ugādi')+'.','In Karnataka the day smells of <b>pānaka</b> and <b>kosambari</b>: jaggery water and soaked moong salad handed out from roadside stalls, with buttermilk for the heat. Bengaluru turns it into a month of classical music. Telugu country celebrates the wedding of Sītā and Rāma at Bhadrācalam.','This article gives Vālmīki’s birth verses, tells the story from Daśaratha’s sacrifice to the four brothers’ childhood and the whole epic in brief, gives the “Śrīrāma rāma rāmeti” verse, and explains every custom of the day.'],[('z','Why is Rāma born at noon?'),('b','That’s what Vālmīki says, Zappy, and he gives the stars too. Temples still open the cradle at midday.')]),
 glance([('Name','Rāma Navamī, “the ninth of Rāma”; Śrī Rāma Navamī'),('When','Caitra Śukla Navamī, the 9th of the bright fortnight of Caitra; March–April; at midday'),('Birth','To Kausalyā and Daśaratha in Ayodhyā; brothers Bharata (Kaikeyī), Lakṣmaṇa and Śatrughna (Sumitrā)'),('Text','Vālmīki Rāmāyaṇa, Bāla Kāṇḍa 1.18.8–10'),('Season','Ends Vasanta Navarātri, the nine spring nights from Ugādi'),('Karnataka','Pānaka, kosambari, majjige; Bengaluru’s Rāma Navamī music festival; Rāmāyaṇa readings'),('Elsewhere','Sītā-Rāma Kalyāṇa at Bhadrācalam; Ayodhyā; Rāmeśvaram; Sītāmaḍhī')],svg(560,140,'A noon sun over a palace with a cradle',f'<rect width="560" height="140" fill="#e3eaf3"/>'+g(280,36,1,sun(20))+g(280,130,1,palace())+g(450,130,1.3,cradle_baby()))),
 reading('day','THE NINTH OF CAITRA','Why this day',svg(560,160,'Nine small lamps for the nine spring nights, the last one glowing',f'<rect width="560" height="160" fill="#fffaf0"/>'+''.join(g(45+k*60,110,1.4 if k==8 else 1,lamp())+lab(45+k*60,140,str(k+1)) for k in range(9))+lab(285,40,'Vasanta Navarātri: Ugādi to Rāma Navamī')),['<b>The date.</b> Caitra Śukla Navamī: nine days after the lunar new year. In the amānta calendar of Karnataka Caitra begins at the new moon, so Rāma Navamī falls in late March or April.','<b>The hour.</b> The birth is placed at midday (<b>madhyāhna</b>), so the main worship happens around noon: the cradle is rocked, the image bathed, and the birth announced with conches and bells.','<b>Nine nights.</b> The nine days from Ugādi to Rāma Navamī are <b>Vasanta (spring) Navarātri</b>, in which many read the Rāmāyaṇa in nine parts (<i>navāha pārāyaṇa</i>) and finish with the birth on the ninth day; some begin readings on Rāma Navamī and continue after.','<b>Two days in some years.</b> When Navamī straddles two days, almanacs choose the day on which it prevails at midday.'],[('z','Nine nights again? I thought Navarātri was in autumn.'),('b','There are two, Zappy. Autumn’s is for Devī; spring’s ends with Rāma.')],'Nine days, then <b>Rāma at noon</b>.'),
 story('putrakameshti','DAŚARATHA’S SACRIFICE','The pāyasa from the fire',strip('Three panels: King Daśaratha grieving without a son; a radiant being rising from the sacrificial fire with a pot of pāyasa; the three queens sharing it',[panel([(DAS(),1.1),(palace(),.4)],'#e9e3f5',150),panel([(agni(),1.2),(pot('#e0a800'),.8)],'#fde4e4',150),panel([(person('#c0392b'),.9),(person('#e0a800'),.9),(person('#2a9d6f'),.9)],'#fff3cf',150)],['a king without sons','the gift of the fire','three queens']),'Vālmīki Rāmāyaṇa, Bāla Kāṇḍa, chapters 8–17.',['<b>Daśaratha</b>, king of Ayodhyā, ruled well for thousands of years but had no son, and grieved.','On his ministers’ advice he performed the horse sacrifice and then the <b>putrakāmeṣṭi</b>, the rite for a son, with the sage <b>Ṛṣyaśṛṅga</b> as priest.','Meanwhile the gods had asked Viṣṇu to be born as a man to end <b>Rāvaṇa</b>, whom no god or demon could kill. Viṣṇu chose Daśaratha as his father.','From the sacrificial fire rose a radiant being carrying a golden vessel of divine <b>pāyasa</b>, and gave it to the king.','Daśaratha gave half to Kausalyā, a portion to Kaikeyī, and the rest to Sumitrā in two shares. All three queens conceived.'],[('z','Four sons from one pot of pāyasa?'),('b','From one divine gift, Zappy: Viṣṇu shared among four. That’s why the brothers are inseparable.')],'A king’s prayer, <b>the fire’s answer</b>.'),
 verse('v-birth1','Vālmīki Rāmāyaṇa 1.18.8–9','The month, the day and the stars',['tato yajñe samāpte tu ṛtūnāṃ ṣaṭ samatyayuḥ','tataś ca dvādaśe māse caitre nāvamike tithau','nakṣatre ’ditidaivatye svoccasaṃstheṣu pañcasu','graheṣu karkaṭe lagne vākpatāv indunā saha'],svg(200,150,'A night sky with five bright planets and the moon beside Jupiter',f'<rect width="200" height="150" fill="#20243a"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="5" fill="#ffd60a" stroke="none"/>' for x,y in [(30,40),(70,30),(110,50),(150,35),(175,70)])+g(100,100,.9,moon())+'<circle cx="125" cy="98" r="6" fill="#ff8c1a" stroke="none"/>'),'When the sacrifice was over, six seasons passed. Then in the twelfth month, Caitra, on the ninth lunar day, under the star whose deity is Aditi (Punarvasu), with five planets exalted, the ascendant in Cancer, and Jupiter (Vākpati) rising with the moon,',[('ṛtūnāṃ ṣaṭ','six seasons, a year'),('dvādaśe māse','in the twelfth month'),('nāvamike tithau','on the ninth lunar day'),('aditi-daivatye','whose deity is Aditi: Punarvasu'),('sva-ucca','in their exaltation'),('karkaṭe lagne','the ascendant in Cancer')],'<b>A horoscope in verse.</b> Vālmīki gives Rāma’s birth like an astronomer: month, lunar day, nakṣatra (Punarvasu, ruled by Aditi), five exalted planets, Cancer rising, Jupiter with the moon. These two verses are why the festival is the ninth of Caitra, and why astrologers have argued over the date for centuries. The sentence continues on the next page.',k='The <b>ninth of Caitra</b>, under Punarvasu.',note='Text: Vālmīki Rāmāyaṇa 1.18.8–9, text as on heritage.iitk.ac.in (VRAM), set in IAST.'),
 verse('v-birth2','Vālmīki Rāmāyaṇa 1.18.10','Kausalyā gives birth to Rāma',['prodyamāne jagannāthaṃ sarvalokanamaskṛtam','kausalyā ’janayad rāmaṃ sarvalakṣaṇasaṃyutam'],svg(200,150,'Kausalyā holding the newborn Rāma',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,140,1.3,mother('#c0392b'))+g(112,96,.8,baby())+g(170,30,.8,sun(14))),'…as Jupiter rose with the moon, Kausalyā gave birth to Rāma, lord of the world, honoured by all the worlds, endowed with every auspicious mark.',[('prodyamāne','while rising'),('jagat-nātham','the lord of the world'),('sarva-loka-namaskṛtam','saluted by all the worlds'),('ajanayat','gave birth to'),('sarva-lakṣaṇa','all auspicious marks'),('saṃyutam','endowed with')],'<b>The child and the world.</b> Vālmīki calls the newborn <i>jagannātha</i>, lord of the world, in the same breath as he names his mother. The following verses tell of Bharata born to Kaikeyī under Puṣya, and the twins Lakṣmaṇa and Śatrughna to Sumitrā under Āśleṣā, and of Ayodhyā erupting in festival. This verse is often recited at noon on Rāma Navamī as the cradle is rocked.',k='<b>Rāma is born</b>.',note='Text: Vālmīki Rāmāyaṇa 1.18.10, heritage.iitk.ac.in (VRAM), set in IAST. Read his life on our '+L('/vishnu/dashavatara/rama/','Rāma article')+'.'),
 story('childhood','FOUR BROTHERS','Childhood, and Viśvāmitra’s arrival',strip('Three panels: four little brothers playing; the sage Viśvāmitra asking the king for Rāma; Rāma and Lakṣmaṇa walking with the sage, bows in hand',[panel([(child(),.9),(child(),.9),(child(),.9),(child(),.9)],'#fff3cf',150),panel([(sage('#ff8c1a'),1),(DAS(),.9)],'#e9e3f5',150),panel([(sage('#ff8c1a'),.9),(RAMA(),.9),(LAKS(),.8)],'#e3f5e9',150)],['four brothers','the sage’s request','into the forest']),'Bāla Kāṇḍa, chapters 18–22.',['The four princes grew up together, learned the Vedas, archery, riding and statecraft. <b>Lakṣmaṇa</b> was always at <b>Rāma</b>’s side, and <b>Śatrughna</b> at <b>Bharata</b>’s.','When Rāma was still a youth, the sage <b>Viśvāmitra</b> came to court and asked for him: demons were wrecking his sacrifices, and only Rāma could stop them.','Daśaratha, terrified for his boy, refused; Vasiṣṭha persuaded him to trust the sage. Rāma and Lakṣmaṇa went.','On the way Viśvāmitra taught them the mantras <b>Balā</b> and <b>Atibalā</b>, that freed them from hunger and fatigue, and later the divine weapons.','Their adventures began: the demoness Tāṭakā, the protection of the sacrifice, Ahalyā freed, and at last Mithilā, where a great bow of Śiva waited, and Sītā.'],[('z','So Rāma left home very young?'),('b','A teenager with a bow and a teacher, Zappy. The whole epic starts with a father learning to let go.')],'The brothers <b>set out</b>.'),
 story('epic','THE WHOLE RĀMĀYAṆA IN FIVE','From the bow to the throne',strip('Three panels: Rāma breaking Śiva’s bow; Rāma, Sītā and Lakṣmaṇa in the forest; Rāma crowned with Sītā',[panel([(RAMA(),.9),(bow(),1.1)],'#fff3cf',150),panel([(RAMA(),.8),(SITA(),.8),(LAKS(),.8),(tree(),.6)],'#e3f5e9',150),panel([(RAMA(),.9),(SITA(),.8),(hanuman(),.7)],'#fde9c8',150)],['the bow breaks','fourteen years','the coronation']),'The story the festival celebrates, in brief.',['At Mithilā Rāma lifted and broke Śiva’s great bow and won <b>Sītā</b>; his three brothers married her sister and cousins.','On the eve of his coronation, Queen Kaikeyī claimed two old boons: Bharata as king, Rāma exiled for fourteen years. Rāma went gladly, with Sītā and Lakṣmaṇa; Daśaratha died of grief, and Bharata ruled only as regent, Rāma’s sandals on the throne.','In the forest <b>Rāvaṇa</b> carried Sītā off to Laṅkā. Rāma found allies in Kiṣkindhā (in today’s Karnataka, by Hampi), above all <b>Hanumān</b>, who leapt the sea and found her.','With a monkey army and a bridge across the ocean, Rāma fought and killed Rāvaṇa, and won Sītā back.','He returned to Ayodhyā and was crowned. Rāma-rājya, his reign, became India’s byword for just rule.'],[('z','Kiṣkindhā is in Karnataka?'),('b','By tradition, around Hampi and Ānegondi, Zappy. Read our '+L('/festivals/hanuman-jayanti/','Hanumān Jayantī')+' article for Añjanādri.')],'Duty, exile, <b>and return</b>.'),
 reading('kalyana','SĪTĀ-RĀMA KALYĀṆA','The wedding celebrated on the birthday',svg(560,170,'Images of Rāma and Sītā seated under a decorated wedding canopy with a priest and a fire',f'<rect width="560" height="170" fill="#e3eaf3"/>'+'<path d="M140 30 h280 M150 30 v120 M410 30 v120" stroke="#e0a800" stroke-width="6"/>'+''.join(f'<path d="M{x} 30 q8 14 16 0" fill="none" stroke="#2f7a3a" stroke-width="3"/>' for x in range(150,410,16))+g(240,150,1.1,RAMA())+g(320,150,1,SITA())+g(470,150,1,sage('#ff8c1a'))+g(90,150,1,agni())),['<b>Birth and wedding together.</b> In Telugu country and many South Indian temples, Rāma Navamī is also celebrated as the <b>kalyāṇa</b>, the wedding, of Sītā and Rāma: the images are married with the full ritual, mangala-sūtra and all.','<b>Bhadrācalam.</b> The most famous is at <b>Bhadrācalam</b> on the Godāvarī in Telaṅgāṇa, the temple associated with the poet-devotee Bhakta Rāmadāsu (Kancharla Gopanna). The state traditionally sends silk clothes and pearls (talambrālu) for the ceremony.','<b>In Karnataka.</b> Many Rāma and Hanumān temples hold a kalyāṇotsava; in homes the noon pūjā is followed by a little cradle ceremony (<b>toṭṭil</b>) for baby Rāma.','<b>Why together.</b> The tradition sees Rāma’s life as one offering: to remember his birth is to remember his marriage, his exile and his rule. Some places hold the wedding on Rāma Navamī, others in the days after.'],[('z','A wedding on his birthday?'),('b','Rāma without Sītā is half the story, Zappy. So the temples celebrate both on one day.')],'Born and married <b>in one celebration</b>.'),
 verse('v-ramanama','Śrīrāma rāma rāmeti','The name equal to a thousand',['śrīrāma rāma rāmeti rame rāme manorame','sahasranāma tattulyaṃ rāmanāma varānane'],svg(200,150,'The name Rāma written three times inside a glowing circle',f'<rect width="200" height="150" fill="#e3eaf3"/>'+'<circle cx="100" cy="72" r="52" fill="#fff8e7"/>'+txt(100,58,'rāma',18,fill='#1d4f8a')+txt(100,80,'rāma',18,fill='#1d4f8a')+txt(100,102,'rāma',18,fill='#1d4f8a')),'“Śrī Rāma, Rāma, Rāma”: thus I delight in Rāma, the delightful one. O lovely-faced one, the name of Rāma is equal to the thousand names.',[('rāma rāma','the name repeated'),('rame','I delight'),('manorame','in the one who delights the mind'),('sahasranāma','the thousand names'),('tat-tulyam','equal to that'),('varānane','O lovely-faced one (Pārvatī)')],'<b>Śiva’s answer.</b> At the close of the Viṣṇu Sahasranāma, Pārvatī asks for a short way to say the thousand names, and Śiva gives this verse: saying “Rāma” three times equals the whole. Many recite it 108 times on Rāma Navamī, and it closes countless pūjās in Karnataka homes.',k='<b>Rāma</b>, three times.',note='Text as on our '+L('/vishnu/vishnu-sahasranama/part-10/','Viṣṇu Sahasranāma, part 10')+' page (verse 27 of the closing).'),
 cards('karnataka','RĀMA NAVAMĪ IN KARNATAKA','Pānaka, kosambari and majjige',fig_row('A cup of pānaka, a plate of kosambari, a pot of buttermilk and a stall',[(panaka(),1.6),(kosambari(),1.6),(pot('#e9e3d0'),1.3),('<rect x="-30" y="-40" width="60" height="40" fill="#e0a800"/><path d="M-34 -40 l34 -16 l34 16" fill="#c0392b"/>',1.2)],['pānaka','kosambari','majjige','aravaṭṭige'],gy=150),[('🥤','Pānaka','Jaggery water with dry ginger, cardamom and pepper, sometimes lemon: offered to Rāma and drunk as prasāda. In the summer heat it is the taste of the day.'),('🥗','Kosambari','Soaked moong or bengal gram with cucumber, carrot, coconut and lemon, seasoned with mustard: cool, light and offered with the pānaka.'),('🥛','Majjige','Spiced buttermilk with ginger, curry leaves and coriander, ladled out to everyone who passes.'),('🏮','Street stalls','Neighbourhoods set up stalls (<i>aravaṭṭige</i>, shelters for giving water) under awnings and hand out pānaka, kosambari and majjige free to all comers, a tradition of serving travellers in the heat.')],[('z','Why such cool food?'),('b','It’s April in Karnataka, Zappy. Rāma’s birthday is the hottest festival of the year, so we serve what the heat needs.')],'Cool food for <b>a hot birthday</b>.'),
 reading('music','BENGALURU’S RĀMA NAVAMĪ MUSIC','A month of concerts for Rāma',svg(560,160,'A singer with a tambura, a violinist and a mṛdaṅga player on a stage with Rāma’s picture',f'<rect width="560" height="160" fill="#e3eaf3"/>'+'<rect x="60" y="120" width="440" height="40" fill="#c9a06a"/>'+g(160,120,1,person('#c0392b',seat=True))+g(280,120,1,person('#2a5aa8',seat=True))+g(400,122,1,mrdanga())+g(280,40,.6,RAMA())+'<rect x="252" y="0" width="56" height="44" fill="none" stroke="#e0a800" stroke-width="4"/>'),['<b>The festival.</b> Bengaluru keeps Rāma Navamī with one of India’s longest classical music festivals, organised for decades by the <b>Sree Ramaseva Mandali</b> in Chāmarājapēṭe: about a month of Karnāṭaka and Hindustānī concerts by the great names of each generation, under a pandal, in Rāma’s honour.','<b>Tyāgarāja.</b> The music is soaked in Rāma: the saint-composer Tyāgarāja (eighteenth–nineteenth century) devoted almost all his songs to Rāma, and his kṛtis are the backbone of these concerts. Purandara Dāsa and the Haridāsas of Karnataka also sang Rāma in Kannada.','<b>Neighbourhood bhajans.</b> Beyond the big stage, every locality has its own Rāma Navamī: bhajana maṇḍaḷis, harikathā, street pandals with a Rāma picture, pānaka and music into the night.','<b>Rāmāyaṇa readings.</b> Temples and homes read the Rāmāyaṇa (Vālmīki in Sanskrit, or Kannada retellings such as Kumāra Vālmīki’s Torave Rāmāyaṇa) in the nine days, ending with the birth.'],[('z','A month of concerts?'),('b','Ask any Bengaluru music lover, Zappy. Rāma Navamī is when the city’s concert year begins.')],'Rāma <b>in music</b>.'),
 cards('temples','RĀMA IN KARNATAKA’S LANDSCAPE','Hampi, Kiṣkindhā and the hills',fig_row('A temple, a hill, a bow and Hanumān',[(palace(),.8),(mountain(),.9),(bow(),1.4),(hanuman(),.8)],['Hampi','Rāmadēvara Beṭṭa','bow','Hanumān'],gy=150),[('🏛️','Hampi','The <b>Hazāra Rāma</b> temple, the Vijayanagara kings’ royal chapel, carries the Rāmāyaṇa carved in panels round its walls; the Kōdaṇḍarāma temple stands by the Tuṅgabhadrā.'),('🐒','Kiṣkindhā','Tradition places Sugrīva’s kingdom around Ānegondi across the river, with <b>Añjanādri</b> hill as Hanumān’s birthplace and Ṛṣyamūka and Pampā sarovara nearby.'),('⛰️','Rāmadēvara Beṭṭa','A hill near Rāmanagara with a Rāma temple and vulture sanctuary, where Jaṭāyu’s story is remembered by local tradition.'),('🛕','Everywhere','Almost every Karnataka village has a Rāma or Āñjaneya temple; Rāma Navamī is its festival, with a car procession in many towns.')],[('z','Karnataka has so much Rāmāyaṇa?'),('b','Half the Kiṣkindhā Kāṇḍa happens here, Zappy, by tradition. Hampi is the Rāmāyaṇa in stone.')],'The epic <b>on our map</b>.'),
 reading('meaning','WHAT RĀMA NAVAMĪ MEANS','Dharma with a human face',svg(560,150,'Rāma holding his bow, standing calmly with Sītā, Lakṣmaṇa and Hanumān',f'<rect width="560" height="150" fill="#e3eaf3"/>'+'<rect y="125" width="560" height="25" fill="#c9d6e6"/>'+g(230,130,1.2,RAMA())+g(290,130,1.1,SITA())+g(170,130,1,LAKS())+g(360,132,.9,hanuman())),['<b>God as a person.</b> Rāma is Viṣṇu born as a man who suffers as men do: exile, the loss of a father, the loss of a wife, war. Vālmīki calls him <i>vigrahavān dharmaḥ</i>, dharma in a body. Rāma Navamī celebrates the arrival of goodness in human form. (Our reading.)','<b>Keeping one’s word.</b> Rāma goes into exile to keep his father’s word to Kaikeyī; the epic’s whole plot turns on promises kept.','<b>The name.</b> The tradition holds that the name “Rāma” itself carries the power of the person; hence the practice of writing and chanting it, the “Śrī Rāma” at the top of letters, the Rāma-nāma on the lips of the dying.','<b>Service.</b> Karnataka’s free pānaka stalls keep the festival’s spirit: Rāma is honoured by caring for the thirsty stranger.'],[('z','If I could do one thing for Rāma Navamī?'),('b','Read one chapter of the Rāmāyaṇa, Zappy, and give a stranger a cup of pānaka. Rāma would like both.')],'Goodness <b>born among us</b>.'),
 end(i,['<b>When.</b> Caitra Śukla Navamī, at noon; the end of Vasanta Navarātri.','<b>Text.</b> Vālmīki 1.18.8–10: Punarvasu, five exalted planets, Cancer rising.','<b>Story.</b> Daśaratha’s pāyasa, four brothers, the whole epic in five frames.','<b>Customs.</b> Cradle at noon, Sītā-Rāma kalyāṇa, “Śrīrāma rāma rāmeti”.','<b>Karnataka.</b> Pānaka, kosambari, majjige; Bengaluru’s music; Hampi.'],'Previous: '+L('/festivals/ugadi/','Ugādi')+'. Next: '+L('/festivals/naga-panchami/','Nāga Pañcamī')+'.','Rāma Navamī: the birth of Rāma'),
 sources([('Text:','Vālmīki Rāmāyaṇa, Bāla Kāṇḍa 1.18.8–10 (heritage.iitk.ac.in, VRAM); Bāla Kāṇḍa chs. 8–22 for the sacrifice and childhood. “Śrīrāma rāma rāmeti” as on our Viṣṇu Sahasranāma part 10 page.'),('Customs:','Wikipedia, “Rama Navami” (date, customs, kalyāṇotsava, Bhadrācalam, Karnataka’s free pānaka, Bengaluru’s music festival by Sree Ramaseva Mandali).')],'Kiṣkindhā’s location and Añjanādri as Hanumān’s birthplace (tradition; contested by other places); Rāmadēvara Beṭṭa’s Jaṭāyu link (local tradition); the details of the Bhadrācalam offerings; which Kannada Rāmāyaṇas are read (vary).','Bāla Kāṇḍa numbering as on heritage.iitk.ac.in.')]
